{
  "sql": "SELECT p.product_name, SUM(oi.quantity) AS total_quantity FROM commerce.order_items AS oi JOIN commerce.orders AS o ON oi.order_id = o.order_id JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_status <> 'cancelled' AND DATE_PART('year', o.order_date) = 2022 GROUP BY p.product_name ORDER BY 2 DESC LIMIT 20",
  "parameters": [],
  "explanation": "Joins order_items with orders to filter out cancelled orders and restrict the date range to 2022. Joins with products to get the product name. Sums the quantity sold per product, orders by the total quantity in descending order, and limits the result to the top 20 products."
}

{
  "sql": "SELECT p.category, COUNT(DISTINCT o.order_id) AS order_count FROM commerce.orders AS o JOIN commerce.order_items AS oi ON o.order_id = oi.order_id JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY p.category ORDER BY 1 LIMIT 200",
  "parameters": ["2022-12-01", "2023-01-01"],
  "explanation": "This query counts the distinct number of customer orders that contained at least one product from each category during December 2022. It joins the orders table with order_items and products to link orders to product categories. The date filter is applied to the order_date in the orders table to restrict the results to December 2022. The results are grouped by product category."
}

{
  "sql": "SELECT p.category, SUM(oi.quantity * oi.unit_price) AS gross_line_value FROM commerce.order_items AS oi JOIN commerce.products AS p ON oi.product_id = p.product_id JOIN commerce.orders AS o ON oi.order_id = o.order_id WHERE DATE_PART('year', o.order_date) = 2022 GROUP BY p.category ORDER BY 1 LIMIT 200",
  "parameters": [],
  "explanation": "Calculates the gross line value (quantity * unit_price) for each product category in 2022 by joining order_items with products and orders, filtering by the year of the order date, and aggregating the sum of the line values."
}

{
  "sql": "SELECT p.category, SUM(oi.quantity * oi.unit_price - oi.discount_amount) AS net_line_value FROM commerce.order_items AS oi JOIN commerce.products AS p ON oi.product_id = p.product_id JOIN commerce.orders AS o ON oi.order_id = o.order_id WHERE DATE_PART('year', o.order_date) = 2022 GROUP BY p.category",
  "parameters": [],
  "explanation": "Calculates the net line value (quantity * unit_price - discount_amount) for each product category in 2022 by joining order_items with products and orders, filtering by the year of the order date, and aggregating by category."
